  "# {0} Pacote Web / itch.io exportado pelo GBA Studio. - Projeto Engine Pack: `engine-project/` - Manifesto Web: `manifest.json` - Config itch.io: `.itch.toml` - Player Web: `player/` - ROM esperada apos build: `roms/{1}` Para publicar no itch.io, gere a ROM real do Game Boy Advance a partir da pasta `engine-project`, coloque o arquivo final em `roms/{2}` e envie esta pasta como pacote HTML. O pacote inclui o GBA Studio Player com core mGBA-WASM direto. Consulte `licenses/mGBA-MPL-2.0.txt` antes de distribuir publicamente.": [
    "# {0} Pacote Web / itch.io exportado pelo GBA Studio. - Projeto Engine Pack: `engine-project/` - Manifesto Web: `manifest.json` - Config itch.io: `.itch.toml` - Player Web: `player/` - ROM esperada após build: `roms/{1}` Para publicar no itch.io, gere a ROM real do Game Boy Advance a partir da pasta `engine-project`, coloque o arquivo final em `roms/{2}` e envie esta pasta como pacote HTML. O pacote inclui o GBA Studio Player com core mGBA-WASM direto. Consulte `licenses/mGBA-MPL-2.0.txt` antes de distribuir publicamente.",
    "# {0} Package Web/itch.io exported by GBA Studio. - Project Engine Pack: \"engine-project/\" - Web Manifesto: \"manifest.json\" - Config itch.io: ?.itch.toml? - Player Web: \"player/? - expected ROM after build: ?roms/{1}To publish on itch.io, manage the real ROM of the Game Boy Advance from the \"engine-project\" folder, put the final file in \"roms/{2}and send this folder as HTML package. The package includes the GBA Studio Player with core mGBA- Direct WASM. Consult with ?licenses /mGBA-MPL-2.0.txt before publicly distributing.",
    "# {0} Paquete Web/itch.io exportado por GBA Studio. - Proyecto Engine Pack: \"motor-project/\" - Web Manifesto: \"manifest.json\" - Config itch.io: ?.itch.toml? - Jugador Web: \"jugador/? - espera ROM después de la construcción: ?roms/{1}Para publicar en itch.io, gestione la ROM real de la Game Boy Advance de la carpeta \"motor-proyecto\", ponga el archivo final en \"roms/{2}y enviar esta carpeta como paquete HTML. El paquete incluye el GBA Studio Jugador con el núcleo mGBA- WASM directo. Consultar con ?licenses /mGBA-MPL-2.0.txt antes de distribuir públicamente."
  ],
  "# ROM Coloque a ROM Game Boy Advance gerada pelo build em `{0}` nesta pasta.": [
    "# ROM Coloque a ROM Game Boy Advance gerada pelo build em `{0}` nesta pasta.",
    "ROM Put the ROM Game Boy Advance generated by the build in ? {0} ? in this folder.",
    "ROM Pon el ROM Game Boy Advance generado por la construcción en ? {0}? en esta carpeta."
  ],
